always-actions.script:
// Protect direct JSON/transition and detail requests before child actions can read or write.
// The separately installed disposable fixture initializer has its own platform-admin gate.
def p = ec.web.parameters
def fixtureInit = System.getProperty('pos.qa.disposable') == 'true' && ec.user.isInGroup('ADMIN') &&
    ec.web.request.pathInfo?.endsWith('/PosQaAcceptance/initialize')
if (!fixtureInit) {
    def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameters([
        transactionId:p.editTxId ?: p.settleTxId ?: p.transactionId ?: p.lastCompletedId,
        sessionId:p.sessionId, terminalId:p.terminalId, heldId:p.heldId,
        productId:p.productId, customerPartyId:p.customerPartyId,
        templateId:p.templateId, cashEntryId:p.cashEntryId,
        expenseId:p.expenseId, wastageId:p.wastageId, facilityId:p.facilityId, printerId:p.printerId, kotId:p.kotId, waiterId:p.waiterId, qrPaymentId:p.qrPaymentId]).call()
    if (!access?.allowed) throw new org.moqui.context.ArtifactAuthorizationException('You do not have access to this POS organization or record.')
    context.posOrganizationPartyId = access.organizationPartyId
}
